export class QuotePage {
  private readonly router = inject(Router);
  private readonly route = inject(ActivatedRoute);
  private readonly injector = inject(Injector);
  protected readonly store = inject(QuoteState);
  protected readonly page = signal<QuoteRoute | null>(null);
  protected readonly invalid = signal(false);
  private readonly plans = inject(PlanState);
  private checkedRoute?: QuoteRoute;
  private recoverCatalogFor?: Country;
  private routeKey = '';
  private priorPhase: string | undefined;

  constructor() {
    inject(DestroyRef).onDestroy(() => this.plans.leave());
    // The router reuses this component across quote routes.
    this.route.paramMap.pipe(takeUntilDestroyed()).subscribe((params) => {
      const rawCountry = params.get('country');
      const rawStep = params.get('step');
      const country =
        rawCountry === 'CO' || rawCountry === 'CL' ? rawCountry.toLowerCase() : rawCountry;
      const validStep = rawStep === 'details' || rawStep === 'plans' || rawStep === 'summary';
      const recover = this.recoverCatalogFor === country && rawStep === 'plans';
      this.recoverCatalogFor = undefined;
      if (!recover && rawStep !== 'summary') this.plans.leave();
      if (rawStep === 'summary' && this.page()?.country !== country) this.plans.leave();
      this.checkedRoute = undefined;
      if (!isCountry(country)) {
        this.store.leave();
        this.page.set(null);
        this.invalid.set(true);
        return;
      }
      if (rawCountry !== country || !validStep) {
        if (this.page()?.country !== country) this.store.leave();
        this.page.set(null);
        const nextStep = validStep ? rawStep : 'details';
        void this.router.navigate(['/', country, 'quote', nextStep], { replaceUrl: true });
        return;
      }
      this.invalid.set(false);
      const page: QuoteRoute = { country, step: rawStep };
      if (recover) this.checkedRoute = page;
      this.page.set(page);
      this.store.load(country);
    });

    effect(() => {
      const page = this.page();
      const state = this.store.state();
      if (!page || state.phase === 'idle' || state.country !== page.country) return;
      const key = `${page.country}/${page.step}`;
      const previous = key === this.routeKey ? this.priorPhase : undefined;
      this.routeKey = key;
      this.priorPhase = state.phase;
      if (state.phase === 'unavailable') this.focus('configuration-error');
      else if (
        page.step === 'details' &&
        (previous === undefined || (previous === 'loading' && state.phase === 'ready'))
      ) {
        this.focus('screen-heading');
      }
    });

    effect(() => {
      const page = this.page();
      const form = this.store.state();
      if (
        !page ||
        page.step === 'details' ||
        form.phase !== 'ready' ||
        form.country !== page.country
      )
        return;
      if (!this.store.canContinue(page.country)) {
        this.redirect(page.country, 'details');
        return;
      }
      if (this.checkedRoute !== page) {
        this.checkedRoute = page;
        untracked(() => {
          if (page.step === 'summary' && !this.plans.hasCandidate(page.country)) {
            this.redirect(page.country, 'plans');
          } else {
            this.plans.read(page.country, page.step === 'summary' ? 'checking' : 'loading');
          }
        });
      }
      if (page.step === 'summary') this.checkSummary(page);
    });

    effect(() => {
      const page = this.page();
      if (page && this.summaryReady(page)) this.focus('summary-heading');
    });
  }

  protected advance(country: Country) {
    if (this.store.canContinue(country))
      void this.router.navigate(['/', country, 'quote', 'plans']);
  }

  protected openSummary(country: Country) {
    if (this.store.canContinue(country) && this.plans.selected(country)) {
      void this.router.navigate(['/', country, 'quote', 'summary']);
    }
  }

  protected summaryReady(page: QuoteRoute) {
    const view = this.plans.view();
    return (
      page.step === 'summary' &&
      view.phase === 'ready' &&
      view.country === page.country &&
      view.checkedForSummary &&
      this.store.canContinue(page.country) &&
      !!this.plans.selected(page.country)
    );
  }

  private checkSummary(page: QuoteRoute) {
    const view = this.plans.view();
    if (view.phase === 'idle' || view.country !== page.country) return;
    if (
      view.phase === 'unavailable' ||
      (view.phase === 'ready' && view.checkedForSummary && !this.plans.selected(page.country))
    ) {
      this.recoverCatalogFor = page.country;
      this.redirect(page.country, 'plans');
    }
  }

  private redirect(country: Country, step: 'details' | 'plans') {
    void this.router.navigate(['/', country, 'quote', step], { replaceUrl: true });
  }

  private focus(target: string) {
    afterNextRender(() => document.getElementById(target)?.focus(), { injector: this.injector });
  }
}
import {
  decodePlanCatalog,
  isRecord,
  MAX_PLANS,
  type Country,
} from "@quote/contract";

export const PLAN_UID = "api::quote-content.plan";

function minorUnits(value: unknown, country: Country): number | null {
  if (typeof value !== "string" && typeof value !== "number") return null;
  const decimal = /^(\d{1,12})(?:\.(\d{1,2}))?$/.exec(String(value));
  if (!decimal || (country === "cl" && decimal[2])) return null;
  const [, whole, fraction = ""] = decimal;
  return Number(country === "co" ? whole + fraction.padEnd(2, "0") : whole);
}

function entries(value: unknown) {
  return Array.isArray(value)
    ? value.map((entry: unknown) => (isRecord(entry) ? entry["text"] : null))
    : null;
}

export function projectPlans(documents: readonly unknown[], country: Country) {
  if (documents.length > MAX_PLANS) return null;
  const plans = documents.map((plan) => {
    if (
      !isRecord(plan) ||
      plan["country"] !== country ||
      plan["active"] !== true
    )
      return null;
    return {
      id: plan["documentId"],
      name: plan["name"],
      shortDescription: plan["shortDescription"],
      basePrice: {
        amountMinor: minorUnits(plan["basePrice"], country),
        currency: plan["currency"],
      },
      coverages: entries(plan["coverages"]),
      benefits: entries(plan["benefits"]),
      order: plan["order"],
      recommended: plan["recommended"],
    };
  });
  return decodePlanCatalog({ schemaVersion: 1, country, plans }, country);
}
import { isCountry, MAX_PLANS } from "@quote/contract";
import { FORM_UID, projectForm } from "../form-projection";

import { PLAN_UID, projectPlans } from "../plan-projection";

type ReadContext = {
  params: Record<string, unknown>;
  querystring: string;
  set(name: string, value: string): void;
  status: number;
  body: unknown;
};

function startRead(ctx: ReadContext) {
  ctx.set("Cache-Control", "no-store");
  return (status: number, code: string) => {
    ctx.body = { error: { code } };
    ctx.status = status;
  };
}

export default {
  async readForm(ctx: ReadContext) {
    const fail = startRead(ctx);
    const country = ctx.params["country"];
    if (!isCountry(country)) return fail(404, "UNSUPPORTED_COUNTRY");
    if (ctx.querystring) return fail(400, "INVALID_REQUEST");

    let documents;
    try {
      documents = await strapi.documents(FORM_UID).findMany({
        status: "published",
        filters: { country },
        populate: { fields: { populate: ["options", "rules"] } },
        limit: 2,
      });
    } catch {
      strapi.log.error("Quote form document retrieval failed.");
      return fail(503, "CONTENT_UNAVAILABLE");
    }

    if (!documents.length) return fail(404, "FORM_NOT_PUBLISHED");
    const form =
      documents.length === 1 ? projectForm(documents[0], country) : null;
    if (!form) {
      strapi.log.warn("A published quote form configuration was rejected.");
      return fail(503, "FORM_UNAVAILABLE");
    }
    ctx.body = form;
    ctx.status = 200;
  },
  async readPlans(ctx: ReadContext) {
    const fail = startRead(ctx);
    const country = ctx.params["country"];
    if (!isCountry(country)) return fail(404, "UNSUPPORTED_COUNTRY");
    if (ctx.querystring) return fail(400, "INVALID_REQUEST");

    let documents;
    try {
      documents = await strapi.documents(PLAN_UID).findMany({
        status: "published",
        filters: { country, active: true },
        populate: ["coverages", "benefits"],
        limit: MAX_PLANS + 1,
      });
    } catch {
      strapi.log.error("Quote plan document retrieval failed.");
      return fail(503, "CONTENT_UNAVAILABLE");
    }

    const catalog = projectPlans(documents, country);
    if (!catalog) {
      strapi.log.warn("A published quote plan catalog was rejected.");
      return fail(503, "PLANS_UNAVAILABLE");
    }
    ctx.body = catalog;
    ctx.status = 200;
  },
};
import { isRecord, type Country } from "./content.ts";

export const MAX_PLANS = 40;
const MAX_PRICE = 999_999_999_999;
const MAX_LIST_ENTRIES = 20;

export const planCurrency = { co: "COP", cl: "CLP" } as const;
export type PlanPrice = {
  amountMinor: number;
  currency: (typeof planCurrency)[Country];
};

export type Plan = {
  id: string;
  name: string;
  shortDescription: string;
  basePrice: PlanPrice;
  coverages: readonly string[];
  benefits: readonly string[];
  order: number;
  recommended: boolean;
};

export type PlanCatalog = {
  schemaVersion: 1;
  country: Country;
  plans: readonly Plan[];
};

export function isPlanId(value: unknown): value is string {
  return typeof value === "string" && /^[a-z0-9][a-z0-9-]{0,39}$/.test(value);
}

function isNonnegativeInteger(value: unknown): value is number {
  return typeof value === "number" && Number.isSafeInteger(value) && value >= 0;
}

export function decodePlanPrice(
  input: unknown,
  country: Country,
): PlanPrice | null {
  if (!isRecord(input)) return null;
  const { amountMinor, currency } = input;
  if (
    currency !== planCurrency[country] ||
    !isNonnegativeInteger(amountMinor) ||
    amountMinor > MAX_PRICE
  )
    return null;
  return { amountMinor, currency: planCurrency[country] };
}

function isPlanText(value: unknown): value is string {
  return (
    typeof value === "string" && value.length <= 240 && value.trim().length > 0
  );
}

function isTextList(value: unknown): value is string[] {
  return (
    Array.isArray(value) &&
    value.length <= MAX_LIST_ENTRIES &&
    value.every(isPlanText)
  );
}

function decodePlan(value: unknown, country: Country): Plan | null {
  if (!isRecord(value)) return null;
  const {
    id,
    name,
    shortDescription,
    order,
    coverages,
    benefits,
    recommended,
  } = value;
  const basePrice = decodePlanPrice(value["basePrice"], country);
  if (
    !isPlanId(id) ||
    !isPlanText(name) ||
    !isPlanText(shortDescription) ||
    !isNonnegativeInteger(order) ||
    !isTextList(coverages) ||
    !isTextList(benefits) ||
    typeof recommended !== "boolean" ||
    !basePrice
  )
    return null;
  return {
    id,
    name,
    shortDescription,
    order,
    coverages,
    benefits,
    recommended,
    basePrice,
  };
}

export function decodePlanCatalog(
  input: unknown,
  country: Country,
): PlanCatalog | null {
  if (
    !isRecord(input) ||
    input["schemaVersion"] !== 1 ||
    input["country"] !== country
  )
    return null;
  const entries = input["plans"];
  if (!Array.isArray(entries) || entries.length > MAX_PLANS) return null;
  const plans: Plan[] = [];
  const ids = new Set<string>();
  for (const entry of entries) {
    const plan = decodePlan(entry, country);
    if (!plan || ids.has(plan.id)) return null;
    ids.add(plan.id);
    plans.push(plan);
  }
  plans.sort((a, b) => a.order - b.order || (a.id < b.id ? -1 : 1));
  return { schemaVersion: 1, country, plans };
}
export type Country = "co" | "cl";

export function isCountry(value: unknown): value is Country {
  return value === "co" || value === "cl";
}

export function isRecord(value: unknown): value is Record<string, unknown> {
  return !!value && typeof value === "object" && !Array.isArray(value);
}

