  expect(candidate).toMatchObject({
    country: "co",
    price: { currency: "COP" },
  });

  const back = page.getByRole("link", { name: "Volver a datos" });
  const next = page.getByRole("button", { name: "Continuar" });
  await page.keyboard.press("Tab");
