import { decodePlanCatalog, decodePlanPrice } from "../src/index.ts";

const plan = {
  id: "plan-a",
  name: "Esencial",
  shortDescription: "Protección básica",
  basePrice: { amountMinor: 12990050, currency: "COP" },
  coverages: ["Responsabilidad civil"],
  benefits: ["Asistencia"],
  order: 5,
  recommended: false,
};

